-- The shared demo specialist is public, so it must not be able to look up real guardians.
create or replace function public.find_guardian_by_email(p_email text) returns uuid
language plpgsql stable security definer set search_path = '' as $$
begin
  if basira_private.current_role() not in ('specialist', 'admin') or (select auth.uid()) = 'd0000000-0000-4000-a000-000000000001'::uuid then
    raise exception 'only a specialist or admin may resolve a guardian by email' using errcode = '42501';
  end if;
  return (
    select p.id
    from public.profiles p
    join auth.users u on u.id = p.id
    where p.role = 'guardian' and lower(u.email) = lower(btrim(p_email))
    limit 1
  );
end $$;

commit;

